Read the source table in A3:C7 and the lookup keys in E3:F6 from the cached workbook. For each answer row, sum exact Dept+RU matches; if no exact match exists, sum all rows for that Dept. Write the four numeric results into G3:G6 on the active sheet.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)
ws = wb.active

# Use the same sheet for cached values when possible; otherwise fall back to Sheet1.
if ws.title in vals.sheetnames:
    vws = vals[ws.title]
elif "Sheet1" in vals.sheetnames:
    vws = vals["Sheet1"]
else:
    vws = vals.active

key_ws = vals[ws.title] if ws.title in vals.sheetnames else vws

def norm(x):
    if x is None:
        return None
    if isinstance(x, float) and x.is_integer():
        return str(int(x))
    return str(x).strip()

def key(x):
    s = norm(x)
    return s.lower() if s is not None else None

def num(x):
    if isinstance(x, (int, float)):
        return float(x)
    if x is None:
        return 0.0
    try:
        return float(str(x).strip())
    except Exception:
        return 0.0

# Read the data table: Dept, RU, Total
data = []
for r in range(3, vws.max_row + 1):
    d = key(vws.cell(r, 1).value)
    ru = key(vws.cell(r, 2).value)
    t = num(vws.cell(r, 3).value)
    if d is None and ru is None and t == 0.0:
        continue
    data.append((d, ru, t))

# Compute G3:G6
for r in range(3, 7):
    d = key(key_ws.cell(r, 5).value)
    ru = key(key_ws.cell(r, 6).value)

    if d is None:
        ws.cell(r, 7).value = None
        print(r, "no department")
        continue

    exact_sum = 0.0
    dept_sum = 0.0
    has_exact = False

    for dd, rr, tt in data:
        if dd == d:
            dept_sum += tt
            if rr == ru:
                exact_sum += tt
                has_exact = True

    val = exact_sum if has_exact else dept_sum
    if isinstance(val, float) and val.is_integer():
        val = int(val)

    ws.cell(r, 7).value = val
    print(r, d, ru, val)

wb.save(OUT)
